script:
test("60000.00 purchases earn 1100.00 from the 2 percent and 3 percent bands", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 60000.00 }), { rebate: 1100.00, bands: [{ rate: 0.00, portion: 10000.00, amount: 0.00 }, { rate: 0.02, portion: 40000.00, amount: 800.00 }, { rate: 0.03, portion: 10000.00, amount: 300.00 }] });
});
test("exactly 10000.00 purchases earn no rebate and stay in the lower band", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.00 }), { rebate: 0.00, bands: [{ rate: 0.00, portion: 10000.00, amount: 0.00 }, { rate: 0.02, portion: 0.00, amount: 0.00 }, { rate: 0.03, portion: 0.00, amount: 0.00 }] });
});
test("10000.50 purchases earn a 0.01 rebate from the 2 percent band", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.50 }), { rebate: 0.01, bands: [{ rate: 0.00, portion: 10000.00, amount: 0.00 }, { rate: 0.02, portion: 0.50, amount: 0.01 }, { rate: 0.03, portion: 0.00, amount: 0.00 }] });
});
test("exactly 50000.00 purchases earn 800.00 and nothing from the 3 percent band", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 50000.00 }), { rebate: 800.00, bands: [{ rate: 0.00, portion: 10000.00, amount: 0.00 }, { rate: 0.02, portion: 40000.00, amount: 800.00 }, { rate: 0.03, portion: 0.00, amount: 0.00 }] });
});
test("30000.00 purchases earn 400.00 from the 2 percent band", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 30000.00 }), { rebate: 400.00, bands: [{ rate: 0.00, portion: 10000.00, amount: 0.00 }, { rate: 0.02, portion: 20000.00, amount: 400.00 }, { rate: 0.03, portion: 0.00, amount: 0.00 }] });
});
test("10000.26 purchases round a 0.0052 band amount to a 0.01 rebate", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.26 }), { rebate: 0.01, bands: [{ rate: 0.00, portion: 10000.00, amount: 0.00 }, { rate: 0.02, portion: 0.26, amount: 0.0052 }, { rate: 0.03, portion: 0.00, amount: 0.00 }] });
});
test("10000.24 purchases round a 0.0048 band amount to a 0.00 rebate", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.24 }), { rebate: 0.00, bands: [{ rate: 0.00, portion: 10000.00, amount: 0.00 }, { rate: 0.02, portion: 0.24, amount: 0.0048 }, { rate: 0.03, portion: 0.00, amount: 0.00 }] });
});
test("50000.17 purchases round 800.0051 to an 800.01 rebate", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 50000.17 }), { rebate: 800.01, bands: [{ rate: 0.00, portion: 10000.00, amount: 0.00 }, { rate: 0.02, portion: 40000.00, amount: 800.00 }, { rate: 0.03, portion: 0.17, amount: 0.0051 }] });
});
test("9999.99 purchases stay one step below 10000.00 in the 0 percent band", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 9999.99 }), { rebate: 0.00, bands: [{ rate: 0.00, portion: 9999.99, amount: 0.00 }, { rate: 0.02, portion: 0.00, amount: 0.00 }, { rate: 0.03, portion: 0.00, amount: 0.00 }] });
});
test("10000.01 purchases keep a 0.0002 band amount and a 0.00 rebate", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.01 }), { rebate: 0.00, bands: [{ rate: 0.00, portion: 10000.00, amount: 0.00 }, { rate: 0.02, portion: 0.01, amount: 0.0002 }, { rate: 0.03, portion: 0.00, amount: 0.00 }] });
});
test("49999.99 purchases round a 799.9998 band amount to an 800.00 rebate", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 49999.99 }), { rebate: 800.00, bands: [{ rate: 0.00, portion: 10000.00, amount: 0.00 }, { rate: 0.02, portion: 39999.99, amount: 799.9998 }, { rate: 0.03, portion: 0.00, amount: 0.00 }] });
});
test("50000.01 purchases keep an 800.0003 sum and an 800.00 rebate", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 50000.01 }), { rebate: 800.00, bands: [{ rate: 0.00, portion: 10000.00, amount: 0.00 }, { rate: 0.02, portion: 40000.00, amount: 800.00 }, { rate: 0.03, portion: 0.01, amount: 0.0003 }] });
});
test("1.00 purchases stay only in the 0 percent band", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 1.00 }), { rebate: 0.00, bands: [{ rate: 0.00, portion: 1.00, amount: 0.00 }, { rate: 0.02, portion: 0.00, amount: 0.00 }, { rate: 0.03, portion: 0.00, amount: 0.00 }] });
});
test("0.01 purchases stay only in the 0 percent band", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 0.01 }), { rebate: 0.00, bands: [{ rate: 0.00, portion: 0.01, amount: 0.00 }, { rate: 0.02, portion: 0.00, amount: 0.00 }, { rate: 0.03, portion: 0.00, amount: 0.00 }] });
});
test("an extra region field throws unknown field", function () {
  assert.throws(function () {
    code.calculateQuarterlyRebate({ quarterlyPurchases: 60000.00, region: "EU" });
  }, /^unknown field: region$/);
});
test("NaN quarterly purchases throw invalid field", function () {
  assert.throws(function () {
    code.calculateQuarterlyRebate({ quarterlyPurchases: NaN });
  }, /^invalid field: quarterlyPurchases$/);
});
